  "v2.maint.logLevelSaved": "Уровень журнала сохранен: {level}. Перезапустите сервер, чтобы он применился полностью.",
  "v2.maint.cleanupHint": "Объединяет дубликаты альбомов, убирает дубликаты треков, удаляет осиротевшие альбомы и исполнителей и неиспользуемые изображения, затем оптимизирует базу данных. Ваши музыкальные файлы не затрагиваются.",
  "v2.maint.cleanupConfirm": "Запустить очистку сервера? Дубликаты альбомов будут объединены, а дубликаты треков убраны из медиатеки. Отменить это нельзя; ваши музыкальные файлы не затрагиваются.",
  "settings.dedupSameRootOnly": "Объединять только копии из одной папки с музыкой",
  "settings.dedupSameRootOnlyHint": "Включено: копия на жестком диске и идентичная копия на NAS остаются двумя записями. Выключено: Tune оставляет в медиатеке только одну из них. Файлы никогда не удаляются.",
  "settings.dedupSameRootOnlyStateOn": "Текущая настройка: объединяются только копии из одной папки с музыкой. Идентичные копии в двух папках с музыкой (например, на жестком диске и на NAS) остаются двумя записями.",
  "settings.dedupSameRootOnlyStateOff": "Текущая настройка: объединяются все идентичные копии, в какой бы папке с музыкой они ни находились. Копия на жестком диске и такая же на NAS дают одну запись.",
