  "v2.db.migrateHint": "Копирует всю медиатеку в базу данных PostgreSQL, затем перезапускает сервер на ней. Текущая база SQLite сохраняется. Сначала проверьте адрес.",
  "v2.db.migrateConfirm": "Перенести медиатеку в PostgreSQL? Копирование может занять несколько минут, затем сервер перезапустится на PostgreSQL: текущее воспроизведение прекратится. База SQLite сохраняется.",
