  "settings.importDbConfirm": "Импорт «{name}» заменит текущую базу данных.\nБудет создана страховочная резервная копия.\nПосле импорта сервер нужно перезапустить.\n\nПродолжить?",
  "settings.importDbSuccess": "Импорт выполнен",
  "settings.restartToApply": "Перезапустите сервер, чтобы применить изменения.",
  "settings.importDbError": "Ошибка импорта",
  "settings.devicesCleared": "Удалено устройств: {count}",
  "settings.clearLibraryConfirm": "Очистить всю медиатеку? (треки, альбомы, исполнители)\nБудут ПОТЕРЯНЫ, и никакое сканирование их не восстановит: содержимое плейлистов (локальные треки), оценки альбомов, закладки, избранное, собранные вручную бокс-сеты и правки альбомов.\nЗоны, радиостанции, настройки и названия плейлистов сохраняются. Непосредственно перед этим автоматически создается резервная копия базы данных (кроме PostgreSQL).\nПолное сканирование, напротив, сохраняет бокс-сеты и правки альбомов.",
  "settings.libraryCleared": "Медиатека очищена. Запустите сканирование, чтобы восстановить ее.",
  "settings.libraryClearedBackup": "Резервная копия базы данных перед очисткой: {path}",
  "settings.deletionError": "Ошибка при удалении",
  "settings.scanCompleted": "Сканирование завершено: файлов — {scanned}, добавлено — {added}, обновлено — {updated}, удалено — {removed}",
