  "devices.gainTrim": "Подстройка усиления",
  "devices.gainTrimHint": "Сдвиг в dB, применяемый к громкости, отправляемой на это устройство, чтобы выровнять воспринимаемую громкость между зонами. Не влияет на отображаемую громкость.",
  "devices.gainTrimFixedVolume": "Включена фиксированная громкость: подстройка не действует (бит-в-бит).",
  "devices.gainTrimPositiveIgnoredHardware": "Сетевая зона с аппаратной регулировкой громкости: положительная подстройка не действует — Tune никогда не отправляет на устройство громкость выше запрошенной (безопасность). Применяется только отрицательная подстройка.",
  "devices.volumeLimitSafety": "Безопасный предел",
  "devices.volumeLimitComfort": "Комфортный предел",
  "devices.volumeLimitNone": "нет",
  "devices.volumeLimitHint": "Безопасный: Tune никогда его не превышает, откуда бы ни пришла команда (приложение, API, рендерер). Комфортный: выше него громкость повышают только кнопки + и −, но не ползунок. Оставьте пустым, чтобы не ограничивать.",
  "devices.volumeLimitInvalid": "Введите предел от 1 до 100 % или оставьте поле пустым.",
  "devices.volumeLimitInvalidDb": "Введите предел в dB от {min} до {max} или оставьте поле пустым.",
  "devices.volumeLimitComfortAboveSafety": "Комфортный предел не может быть выше безопасного.",
  "devices.volumeLimitHintDb": "Пределы в dB устройства, от {min} до {max} dB. На ползунке: зеленый — ниже комфортного, оранжевый — между комфортным и безопасным, красный — выше безопасного. Комфортный не может превышать безопасный. Оставьте пустым, чтобы не ограничивать.",
  "devices.volumeLimitRefusedPure": "Эта зона в режиме PURE: Tune не трогает в ней громкость, поэтому предел не применяется. Выйдите из режима PURE, чтобы задать его.",
  "devices.volumeLimitRefusedFixed": "У этой зоны фиксированная громкость: ее задает усилитель или ЦАП, поэтому предел не применяется. Выключите фиксированную громкость, чтобы задать его.",
  "devices.volumeLockOn": "Громкость зафиксирована на 100 % в режиме PURE",
  "devices.volumeLockOff": "Громкость в режиме PURE не фиксируется",
