  "settings.cleanupMovedGo": "Открыть инструменты медиатеки",
  "settings.clearLibraryV2Hint": "Стирает индекс (треки, альбомы, исполнители). Вместе с ним теряются: содержимое плейлистов, оценки, закладки, избранное, собранные вручную бокс-сеты и правки альбомов. Музыкальные файлы не удаляются. Непосредственно перед этим создается резервная копия базы данных. Сканирование вернет только треки. Чтобы обновить медиатеку, лучше запустите полное сканирование: оно сохраняет бокс-сеты и правки альбомов.",
