  "renderer.wav24Hint": "Передавать настоящий 24-битный WAV. Предлагается по умолчанию; запрещается, только если проверка обнаружения доказала, что этот рендерер не заявляет ни audio/L24, ни audio/wav.",
  "renderer.depthCapNotRate": "Внимание: ограничение разрядности не ограничивает частоту дискретизации. Файл 96 kHz/24 бита станет 96 kHz/16 бит — по-прежнему 96 kHz. Если ваш рендерер поддерживает не выше 48 kHz, задайте также «Макс. частоту».",
  "renderer.flacAndWavSplitBySource": "«Принудительно WAV» действует только для источников не в FLAC (ALAC, AAC…) — он обходит декодер ALAC рендерера. Ваши файлы FLAC по-прежнему передаются как нативный FLAC.",
  "renderer.wav24Unproven": "Ни одна проверка обнаружения пока не прошла успешно: 24 бита остаются доступными, но ничто не подтверждает, что это устройство умеет их воспроизводить. Нажмите «Проверить» выше.",
  "renderer.wav24Refused": "Проверка обнаружения показала: это устройство не заявляет ни audio/L24, ни audio/wav. 24 бита остаются запрещенными — при их передаче была бы тишина.",
  "renderer.startDelay": "Задержка запуска",
