  "renderer.fluxContinu": "Непрерывный поток между треками",
  "renderer.fluxContinuHint": "Для плееров, которые плохо стыкуют два трека подряд: идущие подряд треки одного формата передаются одним потоком WAV без обработки. При первой смене формата восстанавливается обычный переход между треками.",
  "renderer.probeFailed": "Не удалось прочитать возможности рендерера. Сервер не смог определить точную причину.",
