  "renderer.saveConfigHint": "Эти настройки применяются к устройству сразу при нажатии. Эта кнопка дополнительно сохраняет их постоянную копию, привязанную к этому устройству: ее можно в любой момент вернуть с этого экрана.",
  "renderer.saveConfigNoKey": "У этой зоны нет ни идентификатора выхода, ни имени: сохраненную конфигурацию не к чему привязать.",
