  "settings.dlnaCap16bitHint": "Включите, если hi-res (24 бита) на этом рендерере не звучит, а 16 бит работают (Ruark R3). Перекодирует в 16-битный FLAC вместо прямой передачи 24 бит, которые рендерер не декодирует.",
  "settings.alacPassthroughHint": "Передавать ALAC на этот рендерер как есть (бит-в-бит, без перекодирования в FLAC). Включайте, только если рендерер нативно декодирует ALAC, иначе звука не будет.",
  "settings.aacPassthroughHint": "Передавать AAC на этот рендерер как есть, а не перекодировать в FLAC. Источник уже сжат с потерями, поэтому перекодирование не добавляет качества — оно лишь задерживает начало звучания. Включайте, только если рендерер нативно декодирует AAC, иначе звука не будет.",
  "settings.hqplayerHint": "Подключите Tune к HQPlayer для передискретизации и аудиофильских фильтров. Порт по умолчанию: 4321 (v4/v5) или 8019 (v6).",
