  "settings.cloudDisconnected": "Выполнен выход из облака",
  "settings.signOutConfirm": "Отвязать этот сервер от аккаунта mozaiklabs.fr? Этот сервер будет отвязан от аккаунта: его онлайн-копия медиатеки и его общий доступ в Tune Circle будут удалены, а функции Premium, предоставляемые аккаунтом, перестанут работать (лицензионный ключ остается активным). Потом вы сможете войти снова.",
  "settings.licenseRateLimited": "Слишком много попыток — подождите минуту, прежде чем повторить.",
