  "settings.telemetryHint": "Отправлять статистику использования для улучшения Tune: идентификатор экземпляра, версию, платформу, размеры медиатеки, подключенные сервисы и модели устройств.",
  "settings.telemetryOffScope": "Ее выключение также отключает обмен метаданными сообщества и их загрузку. Проверка лицензии при этом продолжает работать, поэтому Premium никогда не теряется.",
  "settings.communitySync": "Обмен метаданными с сообществом",
  "settings.communitySyncHint": "Участвовать в обогащении данных сообществом: сопоставление с MusicBrainz, жанры и сведения об участниках (композитор, дирижер, исполнители), общие для серверов Tune. Анонимно — ваши файлы никогда не передаются.",
  "settings.cloudListens": "Отправлять мои прослушивания в мой аккаунт",
  "settings.cloudListensHint": "Добавляет прослушивания этого сервера на страницу «Мои прослушивания» вашего аккаунта, вместе с прослушиваниями других ваших серверов Tune. Для каждого прослушивания передаются: дата, длительность, анонимный идентификатор профиля, название, исполнитель, альбом и, если известны, ISRC и идентификатор MusicBrainz. Пути к файлам, IP-адрес и названия зон не передаются никогда. По умолчанию выключено.",
  "settings.cloudListensLink": "Мои прослушивания на mozaiklabs.fr",
  "settings.cloudListensConsentTitle": "Делиться прослушиваниями с вашим аккаунтом mozaiklabs.fr?",
  "settings.cloudListensConsentIntro": "Tune может добавлять прослушивания этого сервера в ваш аккаунт mozaiklabs.fr. Пока вы не ответите, ничего не отправляется.",
  "settings.cloudListensConsentSentLabel": "Что отправляется:",
  "settings.cloudListensConsentSent": "для каждого прослушивания — дата, длительность, название, исполнитель, альбом, анонимный идентификатор профиля и, если известны, идентификаторы ISRC и MusicBrainz.",
  "settings.cloudListensConsentNeverLabel": "Что не отправляется никогда:",
  "settings.cloudListensConsentNever": "пути к вашим файлам, ваш IP-адрес, названия зон и имена профилей.",
  "settings.cloudListensConsentBenefit": "Что вы получаете: страницу «Мои прослушивания», где собраны прослушивания всех ваших серверов Tune, и прослушивания сообщества.",
  "settings.cloudListensConsentSettingsReminder": "Вы можете изменить решение в любой момент в разделе Настройки › Система.",
  "settings.cloudListensConsentError": "Не удалось сохранить ответ. Повторите попытку.",
  "settings.cloudListensConsentNo": "Нет",
  "settings.cloudListensConsentYes": "Да, делиться",
  "settings.cloudListensConsentClose": "Закрыть без ответа",
  "settings.communityShare": "Делиться моими оценками и прослушиваниями с сообществом (анонимно)",
  "settings.communityShareHint": "Отдельно от «Моих прослушиваний», по умолчанию выключено. Ваши оценки альбомов (без комментариев) и прослушивания, полученные вашим аккаунтом ПОСЛЕ включения, попадают в общедоступную анонимную статистику, которая показывается на странице альбома, если в ней участвуют не менее трех разных людей. Индивидуальные данные никогда не показываются. Выключение сразу удаляет ваш вклад.",
  "settings.communityMeasuresReceive": "Получать результаты анализа от сообщества",
  "settings.communityMeasuresReceiveHint": "По умолчанию выключено. Для ваших файлов FLAC сервер запрашивает у mozaiklabs.fr значения ReplayGain, динамического диапазона и акустические отпечатки, уже измеренные на точно таком же сигнале как минимум двумя другими установками. Они заполняют только недостающее: ваши теги и собственные измерения никогда не заменяются. Сайт получает лишь короткий префикс, но никогда — список ваших файлов.",
  "settings.communityMeasuresContribute": "Делиться моими результатами анализа с сообществом",
  "settings.communityMeasuresContributeHint": "По умолчанию выключено. Сервер отправляет на сайт только те измерения, которые сам выполнил для ваших файлов FLAC (ReplayGain, динамический диапазон, акустический отпечаток), с привязкой к подписи сигнала. Пути, названия, имена файлов и аккаунт не передаются: сервер идентифицируется номером установки. Выключение стирает отправленное.",
