  "parental.title": "Родительский контроль",
  "parental.guide.intro": "Контролируйте прослушивание в детском профиле: часы прослушивания, лимит времени на день или неделю, скрытие откровенного контента, заблокированные исполнители, радио и подкасты только из списка.",
  "parental.guide.notAdmin": "Задавать эти правила может только профиль администратора. Переключитесь на профиль администратора в меню аватара и вернитесь сюда.",
  "parental.guide.noChild": "Нет профиля для контроля. Сначала создайте профиль ребенка в разделе «Профили», затем вернитесь сюда. Профиль администратора нельзя поставить под контроль.",
