  "parental.hours.title": "Разрешенные часы прослушивания",
  "parental.hours.hint": "Вне этих интервалов профиль не может запускать воспроизведение. Без интервалов — в любое время. Можно добавить несколько интервалов. Интервал не может переходить через полночь, и прослушивание останавливается в его конечное время. Для периода с 21:00 до 07:00 добавьте 21:00–23:59 и 00:00–07:00: вне интервалов останется только последняя минута перед полуночью.",
