  "v2.cr.badgeZoneTip": "Для этой зоны задано правило переназначения каналов. Оно применяется к трекам с числом каналов {in}, если у альбома нет собственного правила.",
  "v2.cr.lead": "Каждая ячейка показывает, какая часть входа (столбец) идет на выход (строка), в dB. Пустая ячейка — без звука. Tune читает каналы в стандартном порядке файлов FLAC и WAV: для 4 каналов — FL FR BL BR.",
