  "v2.hint.tokensUse": "используются для обогащения метаданных и скробблинга.",
  "v2.hint.spotifyConnect": "Делает зону колонкой в приложении Spotify: она появляется в списке устройств, и воспроизведение идет в эту зону.",
  "v2.spotify.connect.titre": "Хотите просто слушать Spotify на своих колонках?",
  "v2.spotify.connect.texte": "Включите Spotify Connect: Tune появится в приложении Spotify на вашем телефоне, аккаунт разработчика не нужен. Требуется Premium.",
  "v2.spotify.connect.activer": "Включить Spotify Connect",
  "v2.spotify.connect.choisirZone": "Выберите зону на карточке «Spotify Connect», затем включите приемник.",
  "v2.spotify.connect.actif": "Spotify Connect включен: выберите Tune в списке устройств приложения Spotify.",
  "v2.spotify.connect.erreur": "Не удалось включить Spotify Connect. Попробуйте снова на карточке «Spotify Connect».",
  "v2.spotify.connect.compte": "Чтобы просматривать свою медиатеку Spotify в Tune, подключите аккаунт.",
  "v2.spotify.connect.compteBouton": "Подключить мой аккаунт",
  "v2.hint.analysisCost": "Анализ прослушивает десять секунд каждого трека, чтобы вычислить его звуковой отпечаток. Он выполняется в фоне, один раз для каждого трека. Темп определяет, сколько ресурсов машины он занимает: чем быстрее, тем сильнее нагружен процессор.",
  "v2.hint.licenseElsewhere": "Эта лицензия сейчас активна на другом сервере. Функции Premium здесь приостановлены, пока она остается открытой там.",
  "v2.hint.ticketsAccount": "Отслеживание обращений привязано к вашему",
  "v2.hint.noKeyNoTickets": ". На этом сервере не зарегистрирован ключ, поэтому показывать нечего.",
  "v2.hint.processingFromSettings": "Обработка запускается из Настроек — разделы «Медиатека» и «Метаданные».",
  "v2.hint.serverUnreachableDot": "Сервер недоступен.",
  "v2.set.browserZoneExists": "Такая зона уже существует: «{nom}» теперь активная зона.",
  "v2.zone.browserOtherDevice": "«{nom}» — зона браузера, которую этот браузер не воспроизводит (она принадлежит другому устройству): здесь звука не будет.",
  "v2.zone.browserPlayHere": "Воспроизводить на этом устройстве",
  "v2.zone.browserStopHere": "Не воспроизводить здесь",
  "v2.set.browserZoneDuplicates": "Зон браузера уже существует: {n}. Они взаимозаменяемы — достаточно одной.",
  "v2.set.peakMeter": "Пиковый индикатор",
  "v2.set.peakMeterHint": "Только отображение — сигнал не меняется. На панели воспроизведения показываются только лампы: две шкалы для нее слишком широки.",
  "v2.set.barVu": "Панель воспроизведения с VU-метрами",
  "v2.set.barVuHint": "Только отображение — сигнал не меняется. Два стрелочных индикатора по обе стороны от кнопок управления; они заменяют пиковые лампы и мини-спектр. На узкой панели возвращается обычный вид.",
  "v2.set.barOnde": "Полоса прогресса в виде волны",
  "v2.set.barOndeHint": "Только отображение. Полоса прогресса на экране «Сейчас играет» и на панели воспроизведения рисует форму волны трека: воспроизведенная часть цветная, остальное приглушено. Для треков медиатеки, а также для Qobuz и TIDAL с параметром ниже; радио и другие потоки сохраняют обычную полосу.",
  "v2.set.ondeStreaming": "Форма волны для треков стриминга",
  "v2.set.ondeStreamingHint": "Qobuz и TIDAL: после 30 с прослушивания сервер один раз скачивает трек, чтобы вычислить форму волны, и сохраняет ее. Если выключено, у этих треков обычная полоса и ничего не скачивается. Требует полосы прогресса в виде волны.",
  "v2.set.barViz": "Визуализатор на панели воспроизведения",
  "v2.set.barVizHint": "Показывает маленький столбиковый визуализатор (спектр) справа на панели воспроизведения, рядом с сердечком. Только отображение: звук не затрагивается.",
  "v2.set.peakOff": "Нет",
  "v2.set.peakLamps": "Лампы",
  "v2.set.peakDat": "DAT PCM-7030",
  "v2.set.peakIec": "IEC 268-18",
  "v2.hint.startupView": "Экран, с которого открывается Tune. Больше ничего не меняется.",
  "v2.hint.defaultZone": "Зона, выбираемая при запуске, если никакая не была выбрана. Трек, запущенный не задумываясь, пойдет туда.",
  "v2.hint.volumeDisplay": "Как отображается громкость. Децибелы показывают реальное усиление; проценты — это шкала отображения, а не измерение.",
  "v2.hint.ingestMode": "🔴 «Переместить» удаляет файл из исходного места. «Копировать» оставляет его на месте и занимает вдвое больше места.",
  "v2.hint.audioBackend": "Драйвер, через который выводится звук. Для ASIO нужен драйвер от производителя; без него выход молчит.",
  "v2.hint.wasapiMode": "В монопольном режиме Tune забирает звуковую карту себе: поток идет бит-в-бит (bit-perfect), но другие приложения замолкают.",
  "v2.hint.replayGainPreamp": "Смещение, применяемое поверх ReplayGain. Повышение уровня приближает пики к перегрузке — для этого и нужна защита от клиппинга.",
  "v2.hint.replayGainPreventClipping": "Снижает усиление ровно настолько, чтобы ни один пик не превысил предел. Без нее положительный предусилитель может вызвать клиппинг у и без того громкого трека.",
