  "cloudBackup.title": "Резервное копирование в облако",
  "cloudBackup.intro": "Tune сохраняет ваши персональные настройки в Mozaiklabs, шифруя их на этом сервере ключом, которого Mozaiklabs не знает: настройки, зоны, профили и предпочтения, эквалайзеры, избранное, плейлисты и радиостанции. Никогда не сохраняются медиатека, пароли и токены сервисов — за одним исключением: токен Discogs, который передается в зашифрованном виде вместе с остальным. Хранится до трех снимков на машину и до пяти машин на аккаунт; самые старые удаляются.",
  "cloudBackup.statePremium": "Резервное копирование в облако входит в Tune Premium.",
  "cloudBackup.stateNotLinked": "Привяжите этот сервер к своему аккаунту Mozaiklabs (раздел «Cloud» чуть выше), чтобы пользоваться резервным копированием.",
  "cloudBackup.stateDisabled": "Автоматическое резервное копирование выключено.",
  "cloudBackup.stateEnabled": "Автоматическое резервное копирование включено: не чаще раза в день и после каждого изменения, по прошествии {n} мин.",
  "cloudBackup.lastBackup": "Последняя резервная копия: {date}",
  "cloudBackup.lastBackupNever": "Резервных копий пока нет.",
  "cloudBackup.lastError": "Последняя ошибка: {error}",
  "cloudBackup.pending": "Изменение ожидает с {date}.",
  "cloudBackup.passphraseLabel": "Парольная фраза резервной копии",
  "cloudBackup.passphraseConfirm": "Подтвердите парольную фразу",
  "cloudBackup.passphraseHint": "Не менее 10 символов. Она понадобится для восстановления на новой машине. Mozaiklabs ее не знает: если потерять ее вместе с ключом восстановления, резервные копии станут нечитаемыми.",
  "cloudBackup.passphraseTooShort": "Парольная фраза должна содержать не менее 10 символов.",
  "cloudBackup.passphraseMismatch": "Парольные фразы не совпадают.",
