  "v2.xtc.separation": "Целевое разделение (dB)",
  "v2.xtc.separationNote": "Разделение между ушами в точке прослушивания для усредненной модели головы. Чем оно сильнее, тем более окрашенный сигнал получают колонки и тем уже зона оптимального прослушивания (несколько сантиметров).",
