  "upsampling.eyebrow": "Плагин Premium",
  "upsampling.title": "Передискретизация",
  "upsampling.lead": "Повышает частоту дискретизации источника до максимальной, которую принимает ЦАП, в пределах того же семейства (44,1 → 352,8 kHz, 48 → 384 kHz), на локальном выходе. Уровень снижается на 3 dB, а защитный лимитер сдерживает редкие оставшиеся пики: никакого клиппинга. Регулятор громкости Tune возвращает эти 3 dB: уровень совпадает с воспроизведением без передискретизации, пока громкость не выше −3 dB (при 100 % уровень регулируется на ЦАП или предусилителе).",
  "upsampling.noZone": "Выберите зону, чтобы настроить для нее передискретизацию.",
  "upsampling.bitPerfect": "Когда передискретизация включена, она изменяет каждый сэмпл: тракт больше не бит-в-бит. Режим PURE всегда ее обходит, а поток DoP никогда не передискретизируется.",
  "upsampling.enabled": "Передискретизировать эту зону",
  "upsampling.enabledHint": "По умолчанию выключено. Только локальный выход, на ЦАП с измеренными частотами. В macOS и Windows только в общем режиме (не в монопольном и не через ASIO); в Linux также при прямом выходе hw:. Нативный DSD и полностью декодируемые сжатые потоки не передискретизируются.",
  "upsampling.filter": "Фильтр",
  "upsampling.filterHint": "Предлагаются только фильтры, которые эта машина выполняет в реальном времени (с запасом ×3). В скобках — снижение уровня.",
  "upsampling.filterNotAdmitted": "Эта машина не может выполнять этот фильтр в реальном времени: он не будет применен. Выберите другой или повторите измерение машины.",
  "upsampling.target": "Целевая частота",
  "upsampling.targetHint": "Целое кратное частоты источника, но не выше того, что принимает ЦАП.",
  "upsampling.targetMax": "Максимум ЦАП",
  "upsampling.dither": "Дизеринг",
  "upsampling.ditherHint": "Дизеринг самого выхода при уменьшении разрядности: TPDF, без формирования шума.",
  "upsampling.machine": "Тест машины",
  "upsampling.machineResult": "Фильтров, выполняемых на этой машине в реальном времени: {admitted} из {total}.",
  "upsampling.machineNone": "Еще не измерено: измерение выполняется при первом сохранении (несколько секунд).",
  "upsampling.remeasure": "Повторить измерение машины",
  "upsampling.nextTrack": "Сохранено: настройка будет применена к следующему потоку.",
  "upsampling.appliesLater": "Настройка применяется к следующему потоку.",
  "upsampling.saved": "Сохранено.",
  "upsampling.appliesNow": "Настройка применяется сразу: воспроизведение продолжится с той же позиции примерно после секунды тишины.",
  "upsampling.applied": "Применено.",
  "upsampling.appliedRestart": "Применено: воспроизведение продолжается с той же позиции.",
  "upsampling.save": "Сохранить",
  "upsampling.constraint.premium": "Передискретизация входит в Tune Premium: ваши настройки сохраняются и будут применены с Premium.",
  "upsampling.constraint.notInstalled": "Установите плагин «Передискретизация» в разделе «Расширения», чтобы применить ее.",
  "upsampling.constraint.pure": "В этой зоне включен режим PURE: передискретизация обходится.",
  "upsampling.constraint.machineTest": "Машина еще не измерена: сохраните или повторите измерение, чтобы применить.",
  "upsampling.constraint.zoneNotSupported": "Эта зона не выводит звук через локальный выход машины: передискретизация к ней не применяется.",
  "upsampling.constraint.strictBitPerfect": "В этой зоне включен строгий бит-в-бит: он запрещает любое преобразование частоты дискретизации, поэтому передискретизация не применяется. Отключите его в настройках зоны, чтобы включить передискретизацию.",
  "upsampling.filter.polyvalent": "Универсальный (аподизирующий, линейная фаза)",
