  "fiche.waveform.help": "Для проверки сигнала на самых громких участках: пики, клиппинг и компрессия. Клиппинг засчитывается, когда не менее трех сэмплов подряд остаются на полной шкале: скорее всего, сигнал был срезан. Одиночный пик на 0 dBFS (нормализованный трек) не считается. Пик-фактор — это разница между пиком и средним уровнем (невзвешенное RMS): чем он ниже, тем сильнее сжата музыка. Это не PLR по EBU, который измеряется в LUFS.",
