  "nowplaying.eqPureNotice": "В этой зоне включен режим PURE: сигнал передается нетронутым, без какой-либо обработки. Пресеты ниже не будут действовать, пока включен режим PURE.",
  "settings.fixedSampleRate": "Фиксированная частота дискретизации выхода",
  "settings.fixedSampleRateOff": "Выключено",
  "settings.fixedSampleRateHint": "Применяется со следующего трека, в том числе для источников из другого семейства частот. Не действует в режиме PURE или строгом бит-в-бит. Если выше предела выхода, Tune применяет этот предел и показывает его в тракте сигнала.",
