  "settings.zoneExclusiveOff": "Общий",
  "settings.zoneExclusiveHint": "Только для локального устройства этой зоны. В монопольном режиме устройством пользуется только Tune; в общем режиме другие приложения сохраняют свой звук. Применяется сразу, если ничего не воспроизводится, иначе — по окончании текущего воспроизведения.",
  "settings.zoneExclusivePending": "Еще не применено: выход сохраняет свой режим до окончания текущего воспроизведения, либо драйвер навязывает свой (ASIO).",
  "settings.wasapiPeriod": "Период WASAPI в монопольном режиме",
  "settings.wasapiPeriodAuto": "Авто (период драйвера)",
  "settings.wasapiPeriodHint": "Длительность каждого буфера, отправляемого на устройство в монопольном режиме (Windows). «Авто» подходит большинству ЦАП. Если с USB-ЦАП звук время от времени «перескакивает, как заезженная пластинка», попробуйте 50 мс. Применяется со следующего запущенного трека; если драйвер отклоняет значение, Tune возвращается к периоду драйвера.",
  "zone.pauseThisZone": "Пауза: {name}",
  "pareFeu.titre": "Брандмауэр Windows фильтрует Tune в этой сети",
  "pareFeu.corps": "Активная сеть отнесена к профилю «{profils}», а правило брандмауэра для Tune его не охватывает. Поэтому обнаружение устройств UPnP/DLNA и доступ с телефона заблокированы: устройство может отображаться только как AirPlay или ничего не получать.",
  "pareFeu.etapePrive": "Сделайте сеть частной: Параметры Windows ▸ Сеть и Интернет ▸ свойства сети ▸ Сетевой профиль: Частная.",
  "pareFeu.etapeAutoriser": "Или разрешите Tune в этой сети: Безопасность Windows ▸ Брандмауэр и защита сети ▸ Разрешить работу с приложением через брандмауэр ▸ tune-server.exe.",
  "pareFeu.etapeRedemarrer": "Затем перезапустите Tune.",
  "pareFeu.profilDomaine": "Доменная",
  "pareFeu.profilPrive": "Частная",
  "pareFeu.profilPublic": "Общедоступная",
  "pareFeu.corpsBlocage": "Правило брандмауэра блокирует tune-server.exe в этой сети ({profils}): {regles}. Оно имеет приоритет над разрешением, отмеченным в «Разрешить работу с приложением через брандмауэр», где само оно не отображается. Поэтому обнаружение устройств UPnP/DLNA и доступ с телефона остаются заблокированными.",
  "pareFeu.etapeSupprimerBlocage": "Удалите все блокирующие правила с именем {regles} (часто их два: TCP и UDP): Брандмауэр Защитника Windows ▸ Дополнительные параметры ▸ Правила для входящих подключений ▸ правила со значком блокировки ▸ Удалить.",
  "pareFeu.corpsAutreChemin": "Tune разрешен в брандмауэре, но для другого расположения, чем запущенная программа. Поэтому в этой сети ({profils}) обнаружение устройств UPnP/DLNA и доступ с телефона заблокированы.",
  "pareFeu.programmeLance": "Запущенная программа: {chemin}",
  "pareFeu.cheminsAutorises": "Разрешено: {chemins}",
  "pareFeu.etapeAutoriserLance": "Разрешите запущенную программу: Безопасность Windows ▸ Брандмауэр и защита сети ▸ Разрешить работу с приложением через брандмауэр ▸ Разрешить другое приложение… ▸ {chemin}.",
  "pareFeu.etapeAutoriserSeule": "Разрешите Tune в этой сети: Безопасность Windows ▸ Брандмауэр и защита сети ▸ Разрешить работу с приложением через брандмауэр ▸ tune-server.exe.",
