  "settings.fauxHiRes": "Обнаруживать измененные источники",
  "settings.fauxHiResHint": "Tune проверяет, что ваши файлы без потерь (FLAC, WAV, AIFF, ALAC…) действительно содержат то, что заявлено: реально используемые биты и срез спектра, — чтобы выявить передискретизированный CD или файл, сделанный из MP3. Анализ выполняется в фоне и уступает воспроизведению; он прослушивает 12 фрагментов по 5 секунд в каждом треке, что на большой медиатеке может занять несколько часов.",
